const npcFacing={};let cinematic=false;
function canStand(x,y,scene=state.scene){return walkable(x,y,scene)&&!targets(scene).some(t=>t.mark&&Math.abs(t.x-x)<2&&Math.abs(t.y-y)<2)}
function conversationGoals(t){return [[t.x-3,t.y],[t.x+3,t.y],[t.x-1,t.y+3],[t.x+1,t.y+3]].filter(([x,y])=>canStand(x,y))}
function planPath(goals,from=[state.x,state.y]){const todo=[[...from,[]]],seen=new Set();for(let i=0;i<todo.length;i++){const[x,y,steps]=todo[i],key=x+','+y;if(seen.has(key))continue;seen.add(key);if(goals.some(p=>p[0]===x&&p[1]===y))return steps;for(const[dir,[dx,dy]]of Object.entries(dirs)){const a=x+dx,b=y+dy;if(canStand(a,b)&&!seen.has(a+','+b))todo.push([a,b,[...steps,dir]])}}return null}
function faceTarget(t){if(state.y>t.y+1){state.dir='up';npcFacing[t.id]='front'}else if(state.x<t.x){state.dir='right';npcFacing[t.id]='left'}else{state.dir='left';npcFacing[t.id]='right'}}
function move(dir){if(blocked()||cinematic)return;state.dir=dir;const d=dirs[dir],x=state.x+d[0],y=state.y+d[1];if(canStand(x,y)){state.x=x;state.y=y;walkFrame++;lastStep=performance.now();setTimeout(paint,190);save()}paint()}
function pathTo(x,y,autoInteract=true){
  if(blocked()||cinematic)return;stopWalk();const target=targets().find(t=>t.x===x&&t.y===y);
  const goals=target?(target.to?[target.approach||[x,y]]:conversationGoals(target)):[[x,y]];
  const path=planPath(goals);if(!path){toast('這裡是建築或植栽，請點旁邊的空地。');return}
  let index=0;const arrive=()=>{stopWalk();if(target){faceTarget(target);paint();if(autoInteract)interactTarget(target)}};
  if(!path.length){arrive();return}document.body.dataset.walking='true';
  walking=setInterval(()=>{if(blocked()){stopWalk();return}move(path[index++]);if(index===path.length)arrive()},90);
}
