function enterScene(scene){const portal=scenes[state.scene].portals.find(p=>p.to===scene);if(!canEnterPortal(portal)){toast('這裡目前沒有任務，請跟著黃色提示前進。');return}stopWalk();const previous=state.scene;state.scene=scene;[state.x,state.y]=scenes[scene].spawn;state.dir='up';if(scene==='campus'){const door=scenes.campus.portals.find(p=>p.to===(previous==='poolHall'?'pool':previous));if(door?.approach&&canStand(...door.approach,scene))[state.x,state.y]=door.approach;state.dir='down'}else if(scene==='poolHall')state.dir='left';save();paint();const task=currentTask();if(task?.autoEnter&&task.scene===scene)event(task.id)}
