function rushToDormDesk(){const target=targets().find(t=>t.id==='kai'),path=planPath(conversationGoals(target));if(!path?.length){faceTarget(target);paint();return}cinematic=true;$('#next').disabled=true;let index=0;const timer=setInterval(()=>{const dir=path[index++],[dx,dy]=dirs[dir];state.x+=dx;state.y+=dy;state.dir=dir;walkFrame++;lastStep=performance.now();paint();if(index===path.length){clearInterval(timer);cinematic=false;$('#next').disabled=false;faceTarget(target);save();paint()}},70)}
